// NextMovie 内置 cheerio 兼容层（P0）
// 目的：让 CatVod/TVBox 系 ESM 引擎（drpy2.min.js 等）能 import "assets://js/lib/cheerio.min.js"，
// 并提供引擎真正用到的三类能力：
//   cheerio.jp(path, data)       —— JSON 路径取值（json: 规则）/ HTML 选择器取值（回退到宿主 pdfh）
//   cheerio.jinja2(tpl, ctx)     —— drpy 的 {{fl.分类}} 模板替换
//   cheerio.load(html)           —— 极简 DOM 包装（映射到宿主 pdfh/pdfa，覆盖常见 find/text/attr/html/each）
// 不是完整 cheerio：依赖 DOM 操作的站点仍然会退化，属已知边界。

function __g() { return globalThis; }

function __toHtml(x) {
  if (x == null) return '';
  if (typeof x === 'string') return x;
  if (typeof x === 'object' && typeof x._nmHtml === 'string') return x._nmHtml;
  try { return String(x); } catch (e) { return ''; }
}

function __hash(n) { return n }

/* ---------------- JSON 路径 ---------------- */

function __tokens(expr) {
  var body = String(expr || '').replace(/^\$/, '').replace(/^\./, '');
  var out = [];
  var i = 0;
  while (i < body.length) {
    var c = body[i];
    if (c === '.') { i++; continue; }
    if (c === '[') {
      var j = body.indexOf(']', i);
      if (j < 0) break;
      out.push({ bracket: body.slice(i + 1, j).trim() });
      i = j + 1;
      continue;
    }
    var start = i;
    while (i < body.length && body[i] !== '.' && body[i] !== '[') i++;
    out.push({ key: body.slice(start, i) });
  }
  return out;
}

function __step(list, t) {
  var out = [];
  for (var k = 0; k < list.length; k++) {
    var v = list[k];
    if (t.key != null) {
      if (t.key === '*') {
        if (Array.isArray(v)) out = out.concat(v);
        else if (v && typeof v === 'object') out = out.concat(Object.keys(v).map(function (x) { return v[x] }));
        continue;
      }
      if (v == null) continue;
      out.push(v[t.key]);
      continue;
    }
    var b = t.bracket;
    if (!b) continue;
    if (b === '*') {
      if (Array.isArray(v)) out = out.concat(v);
      else if (v && typeof v === 'object') out = out.concat(Object.keys(v).map(function (x) { return v[x]; }));
      continue;
    }
    if (b.charAt(0) === "'" || b.charAt(0) === '"') {
      var key = b.slice(1, -1);
      if (v != null) out.push(v[key]);
      continue;
    }
    if (b.charAt(0) === '?') { out.push(undefined); continue; }
    var n = Number(b);
    if (!isNaN(n) && v != null) out.push(v[n]);
  }
  return out;
}

function __jsonPath(root, expr) {
  var list = [root];
  var toks = __tokens(expr);
  for (var i = 0; i < toks.length; i++) list = __step(list, toks[i]);
  if (list.length === 1) return list[0];
  return list;
}

function __looksJson(s) {
  var t = String(s || '').trim();
  return (t.charAt(0) === '{' && t.charAt(t.length - 1) === '}') ||
         (t.charAt(0) === '[' && t.charAt(t.length - 1));
}

function jp(parse, data) {
  var rule = String(parse == null ? '' : parse).trim();
  if (!rule) return '';
  if (rule.indexOf('||') >= 0) {
    var parts = rule.split('||');
    for (var i = 0; i < parts.length; i++) {
      var one = jp(parts[i], data);
      if (Array.isArray(one)) { if (one.length) return one; }
      else if (one != null && one !== '') return one;
    }
    return '';
  }
  var obj = data;
  if (typeof obj === 'string' && __looksJson(obj)) {
    try { obj = JSON.parse(obj); } catch (e) { obj = data; }
  }
  if (obj != null && typeof obj === 'object' && !Array.isArray(obj)) {
    var got = __jsonPath(obj, rule);
    if (got !== undefined) {
      if (Array.isArray(got)) return got;
      if (got == null) return '';
      if (typeof got === 'object') return got;
      return String(got);
    }
  }
  var html = __toHtml(data);
  if (!html) return '';
  if (typeof pdfh === 'function') {
    try { return pdfh(html, rule) || ''; } catch (e) { return ''; }
  }
  return '';
}

function jpa(parse, data) {
  var rule = String(parse == null ? '' : parse).trim();
  var obj = data;
  if (typeof obj === 'string' && __looksJson(obj)) {
    try { obj = JSON.parse(obj); } catch (e) { obj = data; }
  }
  if (obj != null && typeof obj === 'object' && !Array.isArray(obj)) {
    var got = __jsonPath(obj, rule);
    if (Array.isArray(got)) return got;
    if (got != null && typeof got === 'object') return [got];
    return [];
  }
  var html = __toHtml(data);
  if (typeof pdfa === 'function') {
    try { return pdfa(html, rule) || []; } catch (e) { return []; }
  }
  return [];
}

/* ---------------- jinja2 极简实现 ---------------- */

function __pick(ctx, expr) {
  var path = String(expr || '').split('|')[0].trim();
  var v = ctx;
  var parts = path.split('.');
  for (var i = 0; i < parts.length; i++) {
    if (v == null) return '';
    var p = parts[i].trim();
    if (!p) continue;
    if (p === 'fl' && i === 0 && ctx && ctx.fl) { v = ctx.fl; continue; }
    v = v[p];
  }
  if (v == null) return '';
  if (typeof v === 'object') { try { return JSON.stringify(v); } catch (e) { return ''; } }
  return String(v);
}

function jinja2(tpl, ctx) {
  var s = String(tpl == null ? '' : tpl);
  if (s.indexOf('{{') < 0) return s;
  return s.replace(/\{\{([^}]+)\}\}/g, function (_, expr) {
    return encodeURIComponent(__pick(ctx, expr));
  }).replace(/%7B%7B/g, '{{');
}

/* ---------------- load 极简 DOM 包装 ---------------- */

function __Wrap(html) {
  this._nmHtml = html || '';
}
__Wrap.prototype.toString = function () { return this._nmHtml; };
__Wrap.prototype.text = function () {
  if (typeof pdfh !== 'function') return '';
  try { return pdfh(this._nmHtml, 'Text') || ''; } catch (e) { return ''; }
};
__Wrap.prototype.html = function () { return this._nmHtml; };
__Wrap.prototype.attr = function (name) {
  if (typeof pdfh !== 'function') return '';
  try { return pdfh(this._nmHtml, String(name)) || ''; } catch (e) { return ''; }
};

function __List(html, nodes) {
  this._nmHtml = html || '';
  this._nodes = nodes || [];
  this.length = this._nodes.length;
}
__List.prototype.each = function (fn) {
  for (var i = 0; i < this.length; i++) {
    if (fn.call(this._nodes[i], i, this._nodes[i]) === false) break;
  }
  return this;
};
__List.prototype.eq = function (i) { return new __List(this._nmHtml, [this._nodes[i]]); };
__List.prototype.first = function () { return this.eq(0); };
__List.prototype.text = function () {
  var t = '';
  for (var i = 0; i < this.length; i++) t += (this._nodes[i] ? this._nodes[i].text() : '');
  return t;
};
__List.prototype.attr = function (name) {
  for (var i = 0; i < this.length; i++) {
    var v = this._nodes[i] ? this._nodes[i].attr(name) : '';
    if (v) return v;
  }
  return '';
};
__List.prototype.find = function (sel) { return __findList(this._nmHtml, sel); };
__List.prototype.toString = function () { return this.text(); };

function __findList(html, sel) {
  if (typeof pdfa !== 'function') return new __List(html, []);
  var arr = [];
  try { arr = pdfa(html, String(sel)) || []; } catch (e) { arr = []; }
  var nodes = [];
  for (var i = 0; i < arr.length; i++) nodes.push(new __Wrap(arr[i]));
  return new __List(html, nodes);
}

function load(html) {
  var root = __toHtml(html);
  var api = function (sel) {
    if (typeof sel === 'string') return __findList(root, sel);
    if (sel && typeof sel === 'object' && typeof sel._nmHtml === 'string') return sel;
    return new __List(root, []);
  };
  api.root = function () { return new __Wrap(root); };
  api.html = function () { return root; };
  api.text = function () { return new __Wrap(root).text(); };
  api.contains = function () { return false; };
  return api;
}

var cheerio = { jp: jp, jpa: jpa, jinja2: jinja2, load: load, pdfh: jp, pdfa: jpa };
cheerio.jp2 = jp;
cheerio.default = cheerio;

if (typeof globalThis !== 'undefined') {
  globalThis.cheerio = cheerio;
  if (!globalThis.$ && load) globalThis.$ = load;
}

export default cheerio;
export { jp, jpa, jinja2, load };
